<?php require_once __DIR__.'/includes/functions.php';$admin=require_admin();$q=trim((string)($_GET['q']??''));$stmt=db()->prepare('SELECT u.id,u.name,u.email,u.created_at,r.name AS role FROM users u JOIN roles r ON r.id=u.role_id WHERE u.name LIKE ? OR u.email LIKE ? ORDER BY u.id DESC');$like='%'.$q.'%';$stmt->execute([$like,$like]);$users=$stmt->fetchAll();page_start('Manage users');?><section class="page-head"><span class="eyebrow">ADMINISTRATION</span><h1>User management</h1><p class="muted">Create, browse, edit and remove user accounts.</p></section><div class="panel"><div class="toolbar"><form method="get" class="search"><input aria-label="Search users" name="q" placeholder="Search by name or email" value="<?=e($q)?>"><button class="button secondary" type="submit">Search</button></form><a class="button" href="<?=e(url('user_form.php'))?>">+ Add user</a></div><div class="table-scroll"><table><thead><tr><th>ID</th><th>Name</th><th>Email</th><th>Role</th><th>Joined</th><th>Actions</th></tr></thead><tbody><?php foreach($users as $item):?><tr><td>#<?= (int)$item['id'] ?></td><td><?=e($item['name'])?></td><td><?=e($item['email'])?></td><td><span class="pill"><?=e($item['role'])?></span></td><td><?=e(substr($item['created_at'],0,10))?></td><td><div class="actions"><a href="<?=e(url('user_form.php?id='.$item['id']))?>">Edit</a><?php if((int)$item['id']!==(int)$admin['id']):?><form method="post" action="<?=e(url('delete_user.php'))?>" data-confirm="Delete this user permanently?"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$item['id']?>"><button class="danger-link" type="submit">Delete</button></form><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$users):?><tr><td colspan="6">No users found.</td></tr><?php endif;?></tbody></table></div></div><?php page_end(); ?>
